package main

import (
	"bufio"
	"fmt"
	"os"
)

const MD = 998244353

var ff, gg []int64

func power(a, k int64) int64 {
	res := int64(1)
	a %= MD
	for k > 0 {
		if k&1 == 1 {
			res = res * a % MD
		}
		a = a * a % MD
		k >>= 1
	}
	return res
}

func ch(n, k int) int64 {
	if k < 0 || k > n {
		return 0
	}
	return ff[n] * gg[k] % MD * gg[n-k] % MD
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n int
	var k_ int64
	fmt.Fscan(in, &n, &k_)

	if k_ >= int64(n) {
		fmt.Fprintln(out, 0)
		return
	}

	c := n - int(k_)

	size := n + n
	ff = make([]int64, size)
	gg = make([]int64, size)

	f := int64(1)
	for i := 0; i < size; i++ {
		ff[i] = f
		gg[i] = power(f, MD-2)
		f = f * int64(i+1) % MD
	}

	var ans int64
	for a := 1; a <= c; a++ {
		x := power(int64(a), int64(n)) * ch(c, a) % MD
		if (c-a)%2 == 0 {
			ans += x
		} else {
			ans -= x
		}
	}

	ans %= MD
	if ans < 0 {
		ans += MD
	}

	ans = ans * ch(n, c) % MD

	if k_ > 0 {
		ans = ans * 2 % MD
	}

	fmt.Fprintln(out, ans)
}

