const MD = 998244353

func powMod(a, e int64) int64 {
	res := int64(1)
	a %= MD
	for e > 0 {
		if e&1 == 1 {
			res = res * a % MD
		}
		a = a * a % MD
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n int
	var k int64
	fmt.Fscan(in, &n, &k)

	if k >= int64(n) {
		fmt.Fprintln(out, 0)
		return
	}

	c := n - int(k)

	size := 2 * n
	ff := make([]int64, size)
	gg := make([]int64, size)

	f := int64(1)
	for i := 0; i < size; i++ {
		ff[i] = f
		gg[i] = powMod(f, MD-2)
		f = f * int64(i+1) % MD
